chunk.argumentsDelta:
{"file_path":"src/sheet.js","content":"export function colIndex(letters) {
  if (letters.length === 1) return letters.charCodeAt(0) - 64
  return 26 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 64)
}

export function colName(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const k = i - 27
  return String.fromCharCode(65 + Math.floor(k / 26)) + String.fromCharCode(65 + (k % 26))
}

// Returns {col,row} for a valid in-range address (any case) or null.
export function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  return { col: colIndex(m[1].toUpperCase()), row }
}

export const addrKey = (col, row) => colName(col) + row

function fail(msg) {
  const e = new Error(msg)
  e.sheetError = true
  throw e
}

// Returns Map key -> {col,row,content}
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const cells = new Map()
  lines.forEach((raw, idx) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(line)
    const addrText = m[1]
    const a = parseAddr(addrText)
    if (!a) fail(`error: line ${idx + 1}: invalid cell address ${addrText}`)
    const key = addrKey(a.col, a.row)
    if (cells.has(key)) fail(`error: line ${idx + 1}: cell ${key} is declared twice`)
    cells.set(key, { col: a.col, row: a.row, content: m[2] })
  })
  return cells
}
"}

