{"file_path":"src/eval.js","content":"import { parseAddr, addrKey, colName } from './sheet.js'

class Err {
  constructor(t) {
    this.t = t
  }
}
const E = (t) => new Err(t)
const ERR = E('#ERR!')
const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

// ---------- tokenizer / parser ----------
class ParseFail extends Error {}

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: parseFloat(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] })
      i += m[0].length
    } else if ((m = /^(<=|>=|<>|[<>=+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] })
      i += m[0].length
    } else throw new ParseFail()
  }
  return toks
}

function parseFormula(body) {
  const toks = tokenize(body)
  let p = 0
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const expect = (v) => {
    if (!isOp(v)) throw new ParseFail()
    p++
  }
  const CMP = new Set(['=', '<>', '<', '<=', '>', '>='])
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && CMP.has(toks[p].v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) {
      p++
      return { n: 'bin', op: '^', l, r: pow() }
    }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { n: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw new ParseFail()
    const t = toks[p]
    if (t.k === 'num') {
      p++
      return { n: 'num', v: t.v }
    }
    if (t.k === 'op') {
      if (t.v !== '(') throw new ParseFail()
      p++
      const e = cmp()
      expect(')')
      return { n: 'paren', e }
    }
    p++
    const up = t.v.toUpperCase()
    if (isOp('(')) {
      p++
      const args = []
      if (!isOp(')')) {
        args.push(cmp())
        while (isOp(',')) {
          p++
          args.push(cmp())
        }
      }
      expect(')')
      return { n: 'call', name: up, args }
    }
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') throw new ParseFail()
      const w2 = toks[p++].v
      if (isOp('(')) throw new ParseFail()
      return { n: 'range', a: t.v, b: w2 }
    }
    if (up === 'TRUE') return { n: 'bool', v: true }
    if (up === 'FALSE') return { n: 'bool', v: false }
    return { n: 'ref', a: t.v }
  }
  const tree = cmp()
  if (p !== toks.length) throw new ParseFail()
  return tree
}

// A range anywhere but directly as a call argument makes the cell #ERR!.
function misplacedRange(node, direct = false) {
  switch (node.n) {
    case 'range':
      return !direct
    case 'bin':
      return misplacedRange(node.l) || misplacedRange(node.r)
    case 'un':
    case 'paren':
      return misplacedRange(node.e)
    case 'call':
      return node.args.some((a) => misplacedRange(a, true))
    default:
      return false
  }
}

function collectRefs(node, out) {
  switch (node.n) {
    case 'ref': {
      const a = parseAddr(node.a)
      if (a) out.push(a)
      break
    }
    case 'range': {
      const a = parseAddr(node.a)
      const b = parseAddr(node.b)
      if (a && b) {
        for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
          for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push({ col: c, row: r })
      }
      break
    }
    case 'bin':
      collectRefs(node.l, out)
      collectRefs(node.r, out)
      break
    case 'un':
    case 'paren':
      collectRefs(node.e, out)
      break
    case 'call':
      node.args.forEach((a) => collectRefs(a, out))
      break
  }
}

// ---------- cells ----------
function classify(cell) {
  const c = cell.content
  if (c.startsWith('=')) {
    try {
      const tree = parseFormula(c.slice(1))
      return { kind: 'formula', tree, bad: misplacedRange(tree) }
    } catch (e) {
      if (e instanceof ParseFail) return { kind: 'formula', tree: null, bad: true }
      throw e
    }
  }
  if (c === '') return { kind: 'lit', value: 0 }
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(c)) return { kind: 'lit', value: parseFloat(c) }
  if (ERROR_TOKENS.has(c)) return { kind: 'lit', value: E(c) }
  return { kind: 'lit', value: c }
}

// ---------- evaluation ----------
function toNum(v) {
  if (v instanceof Err) return v
  if (typeof v === 'number') return v
  if (typeof v === 'boolean') return v ? 1 : 0
  return E('#VALUE!')
}
const finite = (x) => (Number.isFinite(x) ? x : E('#DIV/0!'))
const rank = (v) => (typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2)

function cmpStr(a, b) {
  const x = Array.from(a, (ch) => ch.codePointAt(0))
  const y = Array.from(b, (ch) => ch.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}

function compare(a, b) {
  const ra = rank(a)
  const rb = rank(b)
  if (ra !== rb) return ra < rb ? -1 : 1
  if (ra === 0) return a < b ? -1 : a > b ? 1 : 0
  if (ra === 1) return cmpStr(a, b)
  return a === b ? 0 : a ? 1 : -1
}

function makeEvaluator(cells) {
  const info = new Map()
  for (const [k, c] of cells) info.set(k, classify(c))
  const memo = new Map()
  const active = new Set()

  function cellValue(col, row) {
    const key = addrKey(col, row)
    const inf = info.get(key)
    if (!inf) return 0
    if (inf.kind === 'lit') return inf.value
    if (memo.has(key)) return memo.get(key)
    if (active.has(key)) return E('#CYCLE!')
    active.add(key)
    let v
    if (inf.bad) v = ERR
    else v = evalNode(inf.tree)
    active.delete(key)
    memo.set(key, v)
    return v
  }

  function refValue(w) {
    const a = parseAddr(w)
    if (!a) return E('#REF!')
    return cellValue(a.col, a.row)
  }

  // Values contributed by a call argument (ranges expanded).
  function argValues(node) {
    if (node.n === 'range') {
      const a = parseAddr(node.a)
      const b = parseAddr(node.b)
      if (!a || !b) return [E('#REF!')]
      const out = []
      for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
        for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(cellValue(c, r))
      return out
    }
    return [evalNode(node)]
  }

  function evalCall(node) {
    const { name, args } = node
    const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
    if (!known.includes(name)) return E('#NAME?')
    if (name === 'IF') {
      if (args.length !== 3) return ERR
      const cv = argValues(args[0])
      if (cv.length !== 1) return ERR
      const c = cv[0]
