{"file_path":"src/cli.js","content":"#!/usr/bin/env node
import { readFileSync } from 'node:fs'
import { parseSheet } from './sheet.js'
import { runValues, runDeps } from './eval.js'

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}
const input = readFileSync(0, 'utf8')
let cells
try {
  cells = parseSheet(input)
} catch (e) {
  if (e && e.sheetError) {
    process.stderr.write(e.message + '\n')
    process.exit(2)
  }
  throw e
}
const out = args[0] === 'values' ? runValues(cells) : runDeps(cells)
process.stdout.write(out)
"}

